{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 Instance does not have IMDSv2 enforced",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance lacks a metadata_options block, defaulting to allow both IMDSv1 and IMDSv2. Enforcing IMDSv2 (http_tokens = 'required') mitigates Server-Side Request Forgery (SSRF) attacks that can steal temporary credentials."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 Instance has no IAM Role attached",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "LOW",
      "explanation": "While not always a direct vulnerability if the instance doesn't need AWS API access, best practice is to attach an IAM role with least privilege rather than relying on static credentials or having no identity management for cloud resources."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added a metadata_options block to enforce IMDSv2 by setting http_tokens to 'required', which prevents SSRF-based credential theft. Note: Attaching an IAM role was omitted as it requires defining a new resource or variable not present in the original file scope, but enforcing IMDSv2 is a critical hardening step for existing instances."
}
